import Foundation

/// The dsh plugin Perch ships (`packaging/dsh/perch.mjs`, #75), embedded so that every perch and Perch.app carries the
/// plugin that matches it; `source` is generated by scripts/dsh/embed-plugin.sh.
public enum DshPlugin {
    /// Written next to the perch binary the plugin runs (`~/.perch/bin/perch-dsh.mjs`).
    public static let fileName = "perch-dsh.mjs"

    /// Where the plugin goes for `perch`: in the same directory.
    public static func path(nextTo perch: String) -> String {
        URL(fileURLWithPath: perch).deletingLastPathComponent().appendingPathComponent(fileName).path
    }
}

/// dsh (DeepSeek Harness) composes every profile from patch layers, and the home layer `$DSH_HOME/cordis.patch.yml`
/// applies to all of them (profiles created later too). So one `insert` row there mounts Perch's plugin everywhere:
/// no per-profile install, no package manager. The plugin itself is a support file next to the perch binary.
///
/// The file is a YAML list of patch entries and Perch has no YAML library, so, as with Hermes, it is edited as text:
/// one marked block, nothing else touched. Perch adds its block only to a list in block style (`- …` rows), an empty
/// file, or an empty `[]`; any other shape is refused. A file left blank once the block is gone is deleted.
public struct DshPatch: HookFile {
    public let agent = "dsh"
    public let eventNames = ["plugin \(DshPlugin.fileName)"]
    public let location = ConfigLocation(dirVariable: "DSH_HOME", defaultDir: ".dsh", file: "cordis.patch.yml")
    public let installNote: String? = "dsh loads plugins when it starts: restart running dsh sessions."
    public let needsTrust = false
    static let begin = "# >>> perch: added by `perch hooks install dsh`, removed by `perch hooks uninstall dsh` >>>"
    static let end = "# <<< perch <<<"

    public init() {}

    /// What the file holds outside Perch's block.
    enum Shape: Equatable {
        /// Nothing but blank lines and comments.
        case blank
        /// An empty flow list (`[]`) on this line.
        case emptyList(line: Int)
        /// A list in block style.
        case list
        /// Anything Perch can't add a row to as text.
        case other
    }

    public func installing(_ text: String?, path: String, perch: String, wait: Int) throws -> String {
        var lines = Self.withoutBlock(text ?? "").text.components(separatedBy: "\n")
        switch Self.shape(of: lines) {
        case .blank, .list: break
        case .emptyList(let line): lines.remove(at: line)
        case .other:
            throw SetupError("\(path) isn't a YAML list of patch entries in block style (`- …`); add Perch's row by hand (`perch hooks install dsh --dry-run` prints it)")
        }
        var kept = lines.joined(separator: "\n")
        if kept.allSatisfy(\.isWhitespace) { kept = "" }
        if !kept.isEmpty && !kept.hasSuffix("\n") { kept += "\n" }
        return kept + block(perch: HookFiles.shellUnquote(perch))
    }

    public func removing(_ text: String, path: String) throws -> (text: String, removed: Int) {
        let (rest, removed) = Self.withoutBlock(text)
        return (rest, removed ? 1 : 0)
    }

    public func perchHooks(in text: String?, path: String) throws -> String {
        guard let text, let range = Self.blockRange(in: text) else { return "" }
        return String(text[range])
    }

    /// dsh never waits for Perch.
    public func wait(in text: String?) -> Int? { nil }

    public func supportFiles(perch: String) -> [String: String] {
        [DshPlugin.path(nextTo: HookFiles.shellUnquote(perch)): DshPlugin.source]
    }

    public func isBlank(_ text: String) -> Bool {
        Self.shape(of: text.components(separatedBy: "\n")) == .blank
    }

    func block(perch: String) -> String {
        [
            Self.begin,
            "- insert:",
            "    - id: perch",
            "      name: \(Self.quoted(DshPlugin.path(nextTo: perch)))",
            "      config:",
            "        perch: \(Self.quoted(perch))",
            Self.end,
        ].joined(separator: "\n") + "\n"
    }

    /// A YAML single-quoted scalar.
    static func quoted(_ s: String) -> String {
        "'" + s.replacingOccurrences(of: "'", with: "''") + "'"
    }

    static func shape(of lines: [String]) -> Shape {
        let content = lines.indices.filter { i in
            let line = lines[i].trimmingCharacters(in: .whitespaces)
            return !line.isEmpty && !line.hasPrefix("#")
        }
        guard let first = content.first else { return .blank }
        let value = lines[first].split(separator: "#", maxSplits: 1, omittingEmptySubsequences: false).first?
            .trimmingCharacters(in: .whitespaces) ?? ""
        if content.count == 1, value == "[]" { return .emptyList(line: first) }
        // Every top-level line is a list item; the rest are indented continuations.
        let topLevel = content.filter { !" \t".contains(lines[$0].first!) }
        guard topLevel.first == first, topLevel.allSatisfy({ isItem(lines[$0]) }) else { return .other }
        return .list
    }

    private static func isItem(_ line: String) -> Bool {
        line == "-" || line.hasPrefix("- ") || line.hasPrefix("-\t")
    }

    /// The text with Perch's marked block cut out, and whether there was one.
    static func withoutBlock(_ text: String) -> (text: String, removed: Bool) {
        guard let range = blockRange(in: text) else { return (text, false) }
        var kept = text
        kept.removeSubrange(range)
        return (kept, true)
    }

    /// Perch's marked block, including the newline after its end marker.
    static func blockRange(in text: String) -> Range<String.Index>? {
        guard let start = text.range(of: begin + "\n"),
              let stop = text.range(of: end, range: start.upperBound..<text.endIndex) else { return nil }
        var upper = stop.upperBound
        if upper < text.endIndex, text[upper] == "\n" { upper = text.index(after: upper) }
        return start.lowerBound..<upper
    }
}
